            assert.ok(isPlainLine(line), `${row.frame.menu}: bad line '${line}'`);
            assert.doesNotMatch(line, /undefined|NaN|\[object/, `${row.frame.menu}: placeholder text in '${line}'`);
        }
        for (const button of row.model.buttons) {
            labels += 1;
